from pathlib import Path
import base64

ROOT = Path(__file__).parent

def source_image(pdf, page, caption):
    image_path = ROOT / f'tmp/pdfs/{pdf}-{page}.png'
    if not image_path.exists():
        import pdfplumber
        source = ROOT / ('存储设备安装调试手册_kr.pdf' if pdf == 0 else '智能巡店摄像头设备安装调试手册_kr.pdf')
        image_path.parent.mkdir(parents=True, exist_ok=True)
        with pdfplumber.open(source) as document:
            document.pages[page - 1].to_image(resolution=100).save(image_path)
    data = base64.b64encode(image_path.read_bytes()).decode()
    return f'<details class="source-image"><summary>원본 화면 보기 · {caption}</summary><figure><img loading="lazy" src="data:image/png;base64,{data}" alt="{caption} 원본 매뉴얼 {page}쪽"><figcaption>{"저장장비" if pdf == 0 else "카메라"} 매뉴얼 PDF {page}쪽. 화면 문구와 위치는 펌웨어에 따라 다를 수 있습니다.</figcaption></figure></details>'

